mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec3 hash3(vec2 p) {
    const vec2 k1 = vec2(127.1, 311.7);
    const vec2 k2 = vec2(269.5, 183.3);
    const vec2 k3 = vec2(419.2, 371.9);
    const float scale = 43758.5453;

    vec3 q = vec3(
        dot(p, k1),
        dot(p, k2),
        dot(p, k3)
    );
    return fract(sin(q) * scale) - 0.5;
}

float hash(vec3 p3) {
    p3 *= 1000.0;
    p3 = fract(p3 * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec3 tid;
float se;

float triangles(vec2 uv) {
    uv.y *= 0.5;
    vec2 id = floor(uv);
    vec2 localPos = fract(uv);
    float triangleID = step(localPos.x, localPos.y);

    tid = vec3(id, triangleID);
    return hash(vec3(id * 0.123 + se, triangleID * 0.321 + se));
}

float trisdf(in vec2 p, in float r) {
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y += r / k;

    if (p.x + k * p.y > 0.0) {
        p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    }
    p.x -= clamp(p.x, -2.0 * r, 0.0);

    return -length(p) * sign(p.y);
}

float det = 0.001;
float tri;
vec3 pos, s;

float de(vec3 p) {
    p.y -= 1.5;
    vec3 p2 = p;

    p2.xz *= rot(iTime);
    p2.xy *= rot(1.0);
    s = sign(p2);
    p2.xy = abs(p2.xy) - 1.2;
    p2.xy *= rot(iTime * 2.0 + s.x);
    p2.xz *= rot(iTime * 3.0 + s.y);
    p2.yz *= rot(iTime * 0.25);

    tri = max(abs(p2.z) - 0.05, abs(trisdf(p2.yx, 0.8)) - 0.15);
    p.x = abs(p.x);
    p.xy *= rot(radians(45.0));

    float flo = p.y + 2.5;
    float d = min(tri * 0.5, flo);
    pos = p;
    return d;
}

vec3 normal(vec3 p) {
    vec2 e = vec2(0.0, det * 2.0);
    return normalize(vec3(
        de(p + e.yxx),
        de(p + e.xyx),
        de(p + e.xxy)
    ) - de(p));
}

vec3 march(vec3 from, vec3 dir, float seed) {
    vec2 pix = 1.0 / iResolution.xy;
    dir.xy += (hash(dir + iTime + seed) - 0.5) * pix;

    vec2 uv = gl_FragCoord.xy / iResolution.xy;
    vec3 p = from, col = vec3(0.0);
    float d = 0.0, td = 0.0, at = 1.0;
    const float maxDist = 50.0;

    for (int b = 0; b < 4; b++) {
        for (int i = 0; i < 70; i++) {
            p += d * dir;
            d = de(p);
            if (d < det || td > maxDist) break;
            td += d;
        }

        vec3 n = normal(p);
        de(p);

        if (d < det) {
            p -= dir * det * 2.0;
            vec3 r = hash3(uv * 10.0 + mod(iTime, 10.0) * 1.234 + n.xy + seed);
            float rso = dot(n, r) < 0.0 ? -1.0 : 1.0;
            vec3 v = normalize(r * rso);

            vec3 c = vec3(0.0);
            if (tri < 0.01) {
                c = normalize(0.5 + hash3(floor(iTime * 5.0) * 0.123 + vec2(s.xy * 23.5)));
            }
            col += abs(c) * at * abs(asin(.9*sin(iTime*5.+s.x+s.y))) * 2.;
            at *= 0.9;

            pos.z += iTime * 3.0;
            float h = triangles(pos.xz * 3.0);
            dir = mix(v, reflect(dir, n), 0.5 + h);
        }
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    uv.y *= iResolution.y / iResolution.x;

    vec3 from = vec3(1.5, sin(iTime) * 0.5, -15.0);
    vec3 dir = normalize(vec3(uv, 1.3 + 0.5 * asin(0.9 * sin(iTime * 0.5))));
    dir.xz *= rot(-0.2 + 0.15 * sin(iTime * 0.3));

    vec3 col = vec3(0.0);
    col += march(from, dir, 1.0);
    col += march(from, dir, 2.0);
    col += march(from, dir, 3.0);
    col += march(from, dir, 4.0);
    col /= 4.0;

    fragColor = vec4(col, 1.0);
}
